properties_schema:
[
  {
    "displayName": "Tip: Get a feel for agents with our quick <a href="https://docs.n8n.io/advanced-ai/intro-tutorial/" target="_blank">tutorial</a> or see an <a href="/workflows/templates/1954" target="_blank">example</a> of how this node works",
    "name": "aiAgentStarterCallout",
    "type": "callout",
    "default": ""
  },
  {
    "displayName": "Source for Prompt (User Message)",
    "name": "promptType",
    "type": "options",
    "default": "auto",
    "options": [
      {
        "name": "Connected Chat Trigger Node",
        "value": "auto",
        "description": "Looks for an input field called ''chatInput'' that is coming from a directly connected Chat Trigger"
      },
      {
        "name": "Define below",
        "value": "define",
        "description": "Use an expression to reference data in previous nodes or enter static text"
      }
    ]
  },
  {
    "displayName": "Prompt (User Message)",
    "name": "text",
    "type": "string",
    "default": "={{ $json.chatInput }}",
    "required": true,
    "displayOptions": {
      "show": {
        "promptType": [
          "auto"
        ]
      }
    },
    "typeOptions": {
      "rows": 2
    }
  },
  {
    "displayName": "Prompt (User Message)",
    "name": "text",
    "type": "string",
    "default": "",
    "required": true,
    "displayOptions": {
      "show": {
        "promptType": [
          "define"
        ]
      }
    },
    "typeOptions": {
      "rows": 2
    }
  },
  {
    "displayName": "Require Specific Output Format",
    "name": "hasOutputParser",
    "type": "boolean",
    "default": false,
    "noDataExpression": true
  },
  {
    "displayName": "Connect an <a data-action=''openSelectiveNodeCreator'' data-action-parameter-connectiontype=''ai_outputParser''>output parser</a> on the canvas to specify the output format you require",
    "name": "notice",
    "type": "notice",
    "default": "",
    "displayOptions": {
      "show": {
        "hasOutputParser": [
          true
        ]
      }
    }
  },
  {
    "displayName": "Enable Fallback Model",
    "name": "needsFallback",
    "type": "boolean",
    "default": false,
    "displayOptions": {
      "show": {
        "@version": [
          {
            "_cnd": {
              "gte": 2.1
            }
          }
        ]
      }
    },
    "noDataExpression": true
  },
  {
    "displayName": "Connect an additional language model on the canvas to use it as a fallback if the main model fails",
    "name": "fallbackNotice",
    "type": "notice",
    "default": "",
    "displayOptions": {
      "show": {
        "needsFallback": [
          true
        ]
      }
    }
  },
  {
    "displayName": "Options",
    "name": "options",
    "type": "collection",
    "default": {},
    "options": [
      {
        "displayName": "System Message",
        "name": "systemMessage",
        "type": "string",
        "default": "You are a helpful assistant",
        "description": "The message that will be sent to the agent before the conversation starts",
        "typeOptions": {
          "rows": 6
        }
      },
      {
        "displayName": "Max Iterations",
        "name": "maxIterations",
        "type": "number",
        "default": 10,
        "description": "The maximum number of iterations the agent will run before stopping"
      },
      {
        "displayName": "Return Intermediate Steps",
        "name": "returnIntermediateSteps",
        "type": "boolean",
        "default": false,
        "description": "Whether or not the output should include intermediate steps the agent took"
      },
      {
        "displayName": "Automatically Passthrough Binary Images",
        "name": "passthroughBinaryImages",
        "type": "boolean",
        "default": true,
        "description": "Whether or not binary images should be automatically passed through to the agent as image type messages"
      },
      {
        "displayName": "Batch Processing",
        "name": "batching",
        "type": "collection",
        "placeholder": "Add Batch Processing Option",
        "description": "Batch processing options for rate limiting",
        "default": {},
        "options": [
          {
            "displayName": "Batch Size",
            "name": "batchSize",
            "default": 1,
            "type": "number",
            "description": "How many items to process in parallel. This is useful for rate limiting, but might impact the log output ordering."
          },
          {
            "displayName": "Delay Between Batches",
            "name": "delayBetweenBatches",
            "default": 0,
            "type": "number",
            "description": "Delay in milliseconds between batches. This is useful for rate limiting."
          }
        ]
      },
      {
        "displayName": "Enable Streaming",
        "name": "enableStreaming",
        "type": "boolean",
        "default": true,
        "description": "Whether this agent will stream the response in real-time as it generates text"
      }
    ],
    "displayOptions": {
      "hide": {
        "@version": [
          {
            "_cnd": {
              "lt": 2.2
            }
          }
        ]
      }
    }
  },
  {
    "displayName": "Options",
    "name": "options",
    "type": "collection",
    "default": {},
    "options": [
      {
        "displayName": "System Message",
        "name": "systemMessage",
        "type": "string",
        "default": "You are a helpful assistant",
        "description": "The message that will be sent to the agent before the conversation starts",
        "typeOptions": {
          "rows": 6
        }
      },
      {
        "displayName": "Max Iterations",
        "name": "maxIterations",
        "type": "number",
        "default": 10,
        "description": "The maximum number of iterations the agent will run before stopping"
      },
      {
        "displayName": "Return Intermediate Steps",
        "name": "returnIntermediateSteps",
        "type": "boolean",
        "default": false,
        "description": "Whether or not the output should include intermediate steps the agent took"
      },
      {
        "displayName": "Automatically Passthrough Binary Images",
        "name": "passthroughBinaryImages",
        "type": "boolean",
        "default": true,
        "description": "Whether or not binary images should be automatically passed through to the agent as image type messages"
      },
      {
        "displayName": "Batch Processing",
        "name": "batching",
        "type": "collection",
        "placeholder": "Add Batch Processing Option",
        "description": "Batch processing options for rate limiting",
        "default": {},
        "options": [
          {
            "displayName": "Batch Size",
            "name": "batchSize",
            "default": 1,
            "type": "number",
            "description": "How many items to process in parallel. This is useful for rate limiting, but might impact the log output ordering."
          },
          {
            "displayName": "Delay Between Batches",
            "name": "delayBetweenBatches",
            "default": 0,
            "type": "number",
            "description": "Delay in milliseconds between batches. This is useful for rate limiting."
          }
        ]
      }
    ],
    "displayOptions": {
      "show": {
        "@version": [
          {
            "_cnd": {
              "lt": 2.2
            }
          }
        ]
      }
    }
  }
]

