          "request": {
            "method": "DELETE",
            "url": "=/collections/{{$parameter["collectionId"]}}/{{$parameter["rowId"]}}"
          },
          "output": {
            "postReceive": [
              {
                "type": "set",
                "properties": {
                  "value": "={{ { "success": true } }}"
                }
              }
            ]
          }
        },
        "action": "Delete a row"
      },
      {
        "name": "Get",
        "value": "get",
        "description": "Retrieve a row",
