        "name": "Get Many",
        "value": "getAll",
        "description": "Retrieve many rows",
        "routing": {
          "request": {
            "method": "GET",
            "url": "=/collections/{{$parameter["collectionId"]}}",
            "qs": {
              "limit": "={{$parameter["limit"]}}"
            }
          },
          "send": {
            "paginate": "={{$parameter["returnAll"]}}"
