operations:
[
  {
    "operation": "appendOrUpdate",
    "name": "Append or Update Row",
    "description": "Append a new row or update an existing one (upsert)"
  },
  {
    "operation": "append",
    "name": "Append Row",
    "description": "Create a new row in a sheet"
  },
  {
    "operation": "clear",
    "name": "Clear",
    "description": "Delete all the contents or a part of a sheet"
  },
  {
    "operation": "create",
    "name": "Create",
    "description": "Create a new sheet"
  },
  {
    "operation": "remove",
    "name": "Delete",
    "description": "Permanently delete a sheet"
  },
  {
    "operation": "delete",
    "name": "Delete Rows or Columns",
    "description": "Delete columns or rows from a sheet"
  },
  {
    "operation": "read",
    "name": "Get Row(s)",
    "description": "Retrieve one or more rows from a sheet"
  },
  {
    "operation": "update",
    "name": "Update Row",
    "description": "Update an existing row in a sheet"
  }
]

properties_schema:
[
  {
    "displayName": "Authentication",
    "name": "authentication",
    "type": "hidden",
    "default": "triggerOAuth2",
    "options": [
      {
        "name": "OAuth2 (recommended)",
        "value": "triggerOAuth2"
      }
    ]
  },
  {
    "displayName": "Document",
    "name": "documentId",
    "type": "resourceLocator",
    "default": {
      "mode": "list",
      "value": ""
    },
    "required": true
  },
  {
    "displayName": "Sheet",
    "name": "sheetName",
    "type": "resourceLocator",
    "default": {
      "mode": "list",
      "value": ""
