    "typeOptions": {
      "loadOptions": {
        "routing": {
          "request": {
            "method": "GET",
            "url": "/models"
          },
          "output": {
            "postReceive": [
              {
                "type": "rootProperty",
                "properties": {
                  "property": "data"
                }
              },
              {
                "type": "filter",
                "properties": {
                  "pass": "={{ $responseItem.active === true && $responseItem.object === "model" }}"
                }
              },
              {
                "type": "setKeyValue",
                "properties": {
                  "name": "={{$responseItem.id}}",
                  "value": "={{$responseItem.id}}"
                }
