      "show": {
        "resource": [
          "reader"
        ],
        "operation": [
          "read"
        ]
      }
    }
  },
  {
    "displayName": "Options",
    "name": "options",
    "type": "collection",
    "default": {},
    "options": [
      {
        "displayName": "Output Format",
        "name": "outputFormat",
        "description": "Specify desired output format",
        "type": "options",
        "options": [
          {
            "name": "HTML",
            "value": "html"
