[
  {
    "displayName": "This node must be connected to an AI chain. <a data-action=''openSelectiveNodeCreator'' data-action-parameter-creatorview=''AI''>Insert one</a>",
    "name": "notice",
    "type": "notice",
    "default": "",
    "typeOptions": {
      "containerClass": "ndv-connection-hint-notice"
    }
  },
  {
    "displayName": "Model",
    "name": "model",
    "type": "options",
    "default": "mistral-small",
    "description": "The model which will generate the completion. <a href="https://docs.mistral.ai/platform/endpoints/">Learn more</a>.",
    "typeOptions": {
      "loadOptions": {
        "routing": {
          "request": {
            "method": "GET",
            "url": "/models"
          },
          "output": {
            "postReceive": [
              {
                "type": "rootProperty",
                "properties": {
                  "property": "data"
                }
              },
              {
                "type": "filter",
                "properties": {
                  "pass": "={{ !$responseItem.id.includes(''embed'') }}"
                }
              },
              {
                "type": "setKeyValue",
                "properties": {
                  "name": "={{ $responseItem.id }}",
                  "value": "={{ $responseItem.id }}"
                }
              },
              {
                "type": "sort",
                "properties": {
                  "key": "name"
                }
              }
            ]
          }
        }
      }
    }
  },
  {
    "displayName": "Options",
    "name": "options",
    "type": "collection",
    "default": {},
    "description": "Additional options to add",
    "options": [
      {
        "displayName": "Maximum Number of Tokens",
        "name": "maxTokens",
        "default": -1,
        "description": "The maximum number of tokens to generate in the completion. Most models have a context length of 2048 tokens (except for the newest models, which support 32,768).",
        "type": "number",
        "typeOptions": {
          "maxValue": 32768
        }
      },
      {
        "displayName": "Sampling Temperature",
        "name": "temperature",
        "default": 0.7,
        "typeOptions": {
          "maxValue": 1,
          "minValue": 0,
          "numberPrecision": 1
        },
        "description": "Controls randomness: Lowering results in less random completions. As the temperature approaches zero, the model will become deterministic and repetitive.",
        "type": "number"
      },
      {
        "displayName": "Max Retries",
        "name": "maxRetries",
        "default": 2,
        "description": "Maximum number of retries to attempt",
        "type": "number"
      },
      {
        "displayName": "Top P",
        "name": "topP",
        "default": 1,
        "typeOptions": {
          "maxValue": 1,
          "minValue": 0,
          "numberPrecision": 1
        },
        "description": "Controls diversity via nucleus sampling: 0.5 means half of all likelihood-weighted options are considered. We generally recommend altering this or temperature but not both.",
        "type": "number"
      },
      {
        "displayName": "Enable Safe Mode",
        "name": "safeMode",
        "default": false,
        "type": "boolean",
        "description": "Whether to inject a safety prompt before all conversations"
      },
      {
        "displayName": "Random Seed",
        "name": "randomSeed",
        "type": "number",
        "description": "The seed to use for random sampling. If set, different calls will generate deterministic results."
      }
    ]
  }
]

