properties_schema:
[
  {
    "displayName": "Mode",
    "name": "mode",
    "type": "options",
    "default": "manual",
    "options": [
      {
        "name": "Manual Mapping",
        "value": "manual",
        "description": "Edit item fields one by one",
        "action": "Edit item fields one by one"
      },
      {
        "name": "JSON",
        "value": "raw",
        "description": "Customize item output with JSON",
        "action": "Customize item output with JSON"
      }
    ],
    "noDataExpression": true
  },
  {
    "displayName": "Duplicate Item",
    "name": "duplicateItem",
    "type": "boolean",
    "default": false
  },
  {
    "displayName": "Duplicate Item Count",
    "name": "duplicateCount",
    "type": "number",
    "default": 0,
    "description": "How many times the item should be duplicated, mainly used for testing and debugging",
    "displayOptions": {
      "show": {
        "duplicateItem": [
          true
        ]
      }
    },
    "typeOptions": {
      "minValue": 0
    }
  },
  {
    "displayName": "Item duplication is set in the node settings. This option will be ignored when the workflow runs automatically.",
    "name": "duplicateWarning",
    "type": "notice",
    "default": "",
    "displayOptions": {
      "show": {
        "duplicateItem": [
          true
        ]
      }
    }
  },
  {
    "displayName": "JSON",
    "name": "jsonOutput",
    "type": "json",
    "default": "{
  "my_field_1": "value",
  "my_field_2": 1
}
",
    "displayOptions": {
      "show": {
        "mode": [
          "raw"
        ]
      }
    },
    "typeOptions": {
      "rows": 5
    }
  },
  {
    "displayName": "Fields to Set",
    "name": "fields",
    "type": "fixedCollection",
    "default": {},
    "description": "Edit existing fields or add new ones to modify the output data",
    "options": [
      {
        "name": "values",
        "displayName": "Values",
        "values": [
          {
            "displayName": "Name",
            "name": "name",
            "type": "string",
            "default": "",
            "placeholder": "e.g. fieldName",
            "description": "Name of the field to set the value of. Supports dot-notation. Example: data.person[0].name.",
            "requiresDataPath": "single"
          },
          {
            "displayName": "Type",
            "name": "type",
            "type": "options",
            "description": "The field value type",
            "options": [
              {
                "name": "String",
                "value": "stringValue"
              },
              {
                "name": "Number",
                "value": "numberValue"
              },
              {
                "name": "Boolean",
                "value": "booleanValue"
              },
              {
                "name": "Array",
                "value": "arrayValue"
              },
              {
                "name": "Object",
                "value": "objectValue"
              }
            ],
            "default": "stringValue"
          },
          {
            "displayName": "Value",
            "name": "stringValue",
            "type": "string",
            "default": "",
            "displayOptions": {
              "show": {
                "type": [
                  "stringValue"
                ]
              }
            },
            "validateType": "string",
            "ignoreValidationDuringExecution": true
          },
          {
            "displayName": "Value",
            "name": "numberValue",
            "type": "string",
            "default": "",
            "displayOptions": {
              "show": {
                "type": [
                  "numberValue"
                ]
              }
            },
            "validateType": "number",
            "ignoreValidationDuringExecution": true
          },
          {
            "displayName": "Value",
            "name": "booleanValue",
            "type": "options",
            "default": "true",
            "options": [
              {
                "name": "True",
                "value": "true"
              },
              {
                "name": "False",
                "value": "false"
              }
            ],
            "displayOptions": {
              "show": {
                "type": [
                  "booleanValue"
                ]
              }
            },
            "validateType": "boolean",
            "ignoreValidationDuringExecution": true
          },
          {
            "displayName": "Value",
            "name": "arrayValue",
            "type": "string",
            "default": "",
            "placeholder": "e.g. [ arrayItem1, arrayItem2, arrayItem3 ]",
            "displayOptions": {
              "show": {
                "type": [
                  "arrayValue"
                ]
              }
            },
            "validateType": "array",
            "ignoreValidationDuringExecution": true
          },
          {
            "displayName": "Value",
            "name": "objectValue",
            "type": "json",
            "default": "={}",
            "typeOptions": {
              "rows": 2
            },
            "displayOptions": {
              "show": {
                "type": [
                  "objectValue"
                ]
              }
            },
            "validateType": "object",
            "ignoreValidationDuringExecution": true
          }
        ]
      }
    ],
    "displayOptions": {
      "show": {
        "@version": [
          3,
          3.1,
          3.2
        ],
        "mode": [
          "manual"
        ]
      }
    },
    "typeOptions": {
      "multipleValues": true,
      "sortable": true
    }
  },
  {
    "displayName": "Fields to Set",
    "name": "assignments",
    "type": "assignmentCollection",
    "default": {},
    "displayOptions": {
      "hide": {
        "@version": [
          3,
          3.1,
          3.2
        ]
      },
      "show": {
        "mode": [
          "manual"
        ]
      }
    }
  },
  {
    "displayName": "Include in Output",
    "name": "include",
