              "multipleValues": false,
              "filter": {
                "caseSensitive": "={{!$parameter.options.ignoreCase}}",
                "typeValidation": "={{ ($nodeVersion < 3.1 ? $parameter.options.looseTypeValidation :  $parameter.looseTypeValidation) ? "loose" : "strict" }}",
